ArrayList  accountList = new ArrayList();

log.error("EDP SAP FF After Operation Rule: Entering" );

if(rawResponseObject != null) {

   log.error("EDP SAP FF After Operation Rule: rawResponseObject is not null" );

    try {
        //create the DocumentBuilder object
        DocumentBuilder builder = DocumentBuilderFactory.newInstance().newDocumentBuilder();
        Document doc = builder.parse(new ByteArrayInputStream(rawResponseObject.getBytes()));

        NodeList nList = doc.getElementsByTagName("item");

    	if (null != nList && nList.getLength() > 0) {
    		log.error("EDP SAP FF After Operation Rule: Length: " + nList.getLength());


    		List<String> userList = new LinkedList<String>();

	        for (int i = 0; null != nList && i < nList.getLength(); i++) {
	            Node nod = nList.item(i);

                DateFormat dateFormat = new SimpleDateFormat( "yyyy-MM-dd" );
                String validTo = nod.getElementsByTagName("VALID_TO").item(0).getTextContent();
                Date today = new Date();
                SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
                Date date;
                try {
                    date = dateFormat.parse(validTo);
                    if(today.compareTo(date) < 0) {
                        if ( !userList.contains(nod.getElementsByTagName("FF_USER").item(0).getTextContent()) ) {
                            userList.add ( nod.getElementsByTagName("FF_USER").item(0).getTextContent());
                        }

                    }
                }
                catch (ParseException e) {
                    log.error("EDP SAP FF After Operation Rule: ParseException");
                }



	        }

	        for(String employeeEntry : userList){

	        	List<String> groupList = new LinkedList<String>();
	        	Map account = new HashMap();

	            for (int i = 0; null != nList && i < nList.getLength(); i++) {

	              	Node nod = nList.item(i);



	              	if ( nod.getElementsByTagName("FF_USER").item(0).getTextContent().contains(employeeEntry)){

                        DateFormat dateFormat = new SimpleDateFormat( "yyyy-MM-dd" );
                        String validTo = nod.getElementsByTagName("VALID_TO").item(0).getTextContent();
                        Date today = new Date();
                        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
                        Date date;
                        try {
                            date = dateFormat.parse(validTo);
                            if(today.compareTo(date) < 0) {

	              		           groupList.add ( nod.getElementsByTagName("FFOBJECT").item(0).getTextContent() + " - " + nod.getElementsByTagName("CONNECTOR").item(0).getTextContent());

                            }
                        }
                        catch (ParseException e) {
                            log.error("EDP SAP FF After Operation Rule: ParseException");
                        }



	              	}

	          	}

	          	account.put("Userid", employeeEntry);
				account.put("FFOBJECT", groupList);
				accountList.add(account);

	        }



        }

    } catch (Exception e) {
        log.info("Error " +  e.getMessage());
		log.error(e.getMessage());
	}

}

